# 레드-블랙 트리 예시: Python 3에서 실행 가능한 코드
node = {"value": 10, "color": "black"}
child = {"value": 7, "color": "red"}
print(node["color"], child["color"])

# 트라이(Trie) 예시: Python 3에서 실행 가능한 코드
trie = {}
for word in ["to", "tea"]:
    cur = trie
    for ch in word:
        cur = cur.setdefault(ch, {})
    cur["$"] = True
print("t" in trie)

# 그래프(Graph) 예시: Python 3에서 실행 가능한 코드
graph = {"A": ["B", "C"], "B": ["A"], "C": ["A"]}
print(graph["A"])

# 가중치 그래프 예시: Python 3에서 실행 가능한 코드
edges = {("A", "B"): 5, ("A", "C"): 2}
print(min(edges, key=edges.get), min(edges.values()))

# 인접 리스트 예시: Python 3에서 실행 가능한 코드
adj = {0: [1], 1: [0, 2], 2: [1]}
for neighbor in adj[1]:
    print(neighbor)

# 스택 오버플로 예시: Python 3에서 실행 가능한 코드
def countdown(n):
    if n == 0:
        return "끝"
    return countdown(n - 1)
print(countdown(3))

# 함수형 자료구조 예시: Python 3에서 실행 가능한 코드
def add_item(items, value):
    return items + (value,)
base = (1, 2)
print(base, add_item(base, 3))

# 트레이(Treap) 예시: Python 3에서 실행 가능한 코드
node = {"key": 10, "priority": 0.42}
left = {"key": 5, "priority": 0.30}
print(left["key"] < node["key"] and left["priority"] < node["priority"])
